CREATE TABLE sellers (id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, plan text NOT NULL DEFAULT 'free', status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, github_user_id bigint UNIQUE, github_login text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE seller_members (seller_id uuid NOT NULL REFERENCES sellers(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL, PRIMARY KEY (seller_id, user_id));
CREATE TABLE sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE github_installations (installation_id bigint PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), account_login text NOT NULL, account_type text NOT NULL, suspended_at timestamptz, uninstalled_at timestamptz);
CREATE TABLE provider_connections (id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), provider text NOT NULL, webhook_secret_enc text NOT NULL, api_key_enc text, key_version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'active', mode text NOT NULL, UNIQUE (seller_id, provider, mode));
CREATE TABLE products (id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), name text NOT NULL, status text NOT NULL DEFAULT 'draft', update_window_days integer, revoke_policy jsonb NOT NULL);
CREATE TABLE deliverables (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), type text NOT NULL, config jsonb NOT NULL);
CREATE TABLE provider_products (id uuid PRIMARY KEY, provider_connection_id uuid NOT NULL REFERENCES provider_connections(id), external_product_id text NOT NULL, external_price_id text NOT NULL, product_id uuid NOT NULL REFERENCES products(id), seats integer NOT NULL DEFAULT 1, UNIQUE (provider_connection_id, external_product_id, external_price_id));
CREATE TABLE licenses (id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), product_id uuid NOT NULL REFERENCES products(id), status text NOT NULL, kind text NOT NULL, seats_total integer NOT NULL, purchased_at timestamptz NOT NULL, updates_until timestamptz, purchase_email text, manager_user_id uuid REFERENCES users(id), status_reason text);
CREATE TABLE license_external_refs (id uuid PRIMARY KEY, license_id uuid NOT NULL REFERENCES licenses(id), provider text NOT NULL, external_order_id text NOT NULL, external_subscription_id text, external_customer_id text, UNIQUE (provider, external_order_id));
CREATE TABLE seats (id uuid PRIMARY KEY, license_id uuid NOT NULL REFERENCES licenses(id), user_id uuid REFERENCES users(id), assigned_at timestamptz, released_at timestamptz);
CREATE TABLE claims (id uuid PRIMARY KEY, license_id uuid NOT NULL REFERENCES licenses(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_count integer NOT NULL DEFAULT 0, max_uses integer NOT NULL DEFAULT 1);
CREATE TABLE grants (id uuid PRIMARY KEY, seat_id uuid NOT NULL REFERENCES seats(id), deliverable_id uuid NOT NULL REFERENCES deliverables(id), desired text NOT NULL, observed text NOT NULL DEFAULT 'none', provenance text, last_reconciled_at timestamptz, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz, github_invitation_id bigint, invite_sent_at timestamptz, invite_count integer NOT NULL DEFAULT 0, UNIQUE (seat_id, deliverable_id));
CREATE TABLE external_events (id uuid PRIMARY KEY, source text NOT NULL, external_event_id text NOT NULL, seller_id uuid REFERENCES sellers(id), received_at timestamptz NOT NULL DEFAULT now(), occurred_at timestamptz, type text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz, process_error text, UNIQUE (source, external_event_id));
CREATE TABLE license_events (id uuid PRIMARY KEY, license_id uuid NOT NULL REFERENCES licenses(id), external_event_id uuid NOT NULL REFERENCES external_events(id), type text NOT NULL, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL, data jsonb NOT NULL, UNIQUE (license_id, external_event_id));
CREATE TABLE activity_log (id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), subject_type text NOT NULL, subject_id uuid NOT NULL, action text NOT NULL, reason text NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drift_items (id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), grant_id uuid REFERENCES grants(id), kind text NOT NULL, details jsonb NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_log (id uuid PRIMARY KEY, "to" text NOT NULL, template text NOT NULL, dedupe_key text NOT NULL UNIQUE, provider_message_id text, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id uuid PRIMARY KEY, actor text NOT NULL, action text NOT NULL, ip inet, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX licenses_seller_id_idx ON licenses (seller_id);
CREATE INDEX external_events_seller_id_idx ON external_events (seller_id);
CREATE INDEX activity_log_seller_id_idx ON activity_log (seller_id);
CREATE INDEX drift_items_seller_id_idx ON drift_items (seller_id);
